function parseLine(input) {
  var ns = str(input.tenant, 80);
  var evs = jparse(input.events);
  if (!Array.isArray(evs)) return { success: true, branch: 'skip', reason: 'no_events' };
  var ev = null;
  for (var i = 0; i < evs.length && !ev; i++) {
    var e = evs[i];
    if (isObj(e) && e.type === 'message' && isObj(e.message) && e.message.type === 'text' && isObj(e.source) && e.source.type === 'user' && typeof e.source.userId === 'string') ev = e;
  }
  if (!ev) return { success: true, branch: 'skip', reason: evs.length ? 'no_text_message_from_user（這一版只處理一對一文字訊息）' : 'verify_ping（沒有事件，LINE 後台按「驗證」會送這個）' };
  var uid = ev.source.userId;
  if (!/^U[0-9a-f]{32}$/i.test(uid)) return { success: true, branch: 'skip', reason: 'bad_user_id' };
  var text = clean(ev.message.text, TEXT_MAX);
  if (!text) return { success: true, branch: 'skip', reason: 'empty_text' };
  var eid = clean(ph(ev.webhookEventId) || ('m' + clean(ph(ev.message.id), 40)), 60).replace(/[^A-Za-z0-9_-]/g, '');
  if (!eid) return { success: true, branch: 'skip', reason: 'no_event_id' };
