  var ts = isFinite(t) && t > 0 ? isoOf(t) : isoOf(nowMs());
  var conv = 'line:' + uid;
  var mid = 'imbot~' + ns + '~m~' + eid;
  return {
    success: true, branch: 'go', conv: conv, conv_q: encodeURIComponent(conv), user_id: uid, text: text, reply_token: clean(ph(ev.replyToken), 200),
    event_id: eid, ts: ts, cid: 'imbot~' + ns + '~c~' + uid, mid: mid,
    claim_body: JSON.stringify({ template: 'imbot_msg', record_id: mid, create_only: true,
      values: { conv: conv, platform: 'line', ts: ts, speaker: 'customer', content: text, directive_id: '', event_id: eid, send_status: '', send_note: '' } })
  };
}

